#include <vector>
#include <omp.h>

void reversePrefixSum(std::vector<int> const& x, std::vector<int> &output) {
    const int n = static_cast<int>(x.size());
    output.resize(n);
    if (n == 0) return;

    const int max_threads = omp_get_max_threads();
    std::vector<long long> chunk_sums(max_threads, 0);

    #pragma omp parallel
    {
        const int tid = omp_get_thread_num();
        const int nt  = omp_get_num_threads();

        const int start = (tid * n) / nt;
        const int end   = ((tid + 1) * n) / nt;

        long long local_sum = 0;
        for (int i = start; i < end; ++i) {
            local_sum += x[i];
            output[i] = static_cast<int>(local_sum);
        }
        chunk_sums[tid] = local_sum;

        #pragma omp barrier

        long long offset = 0;
        for (int t = 0; t < tid; ++t) {
            offset += chunk_sums[t];
        }

        for (int i = start; i < end; ++i) {
            output[i] += static_cast<int>(offset);
        }
    }
}
